const body = $input.first().json.body;

const mockCopy = [
  `🚀 [MOCK] ¡Atención ${body.industria}! Descubre la solución que transforma tu negocio.`,
  `✨ Campaña para ${body.plataforma}: Tono ${body.tono}. Lorem ipsum dolor sit amet, conecta con tu audiencia hoy.`,
  `💡 MarketMind IA generó este copy para campaña #${body.campaign_id}. Industria: ${body.industria}.`,
].join(' ');

return [{
  json: {
    ...body,
    generated_copy: mockCopy,
    imagen_b64: null
  }
}];

const body = $input.first().json.body;

const tonoInstrucciones = {
  profesional: 'Usa un lenguaje formal, corporativo y confiable.',
  casual: 'Usa un lenguaje amigable, cercano y conversacional.',
  urgente: 'Crea urgencia y escasez. Usa verbos de acción y plazos.',
  inspiracional: 'Motiva e inspira. Usa metáforas y lenguaje aspiracional.',
  humoristico: 'Usa humor ligero y witty. Hazlo memorable y entretenido.',
  persuasivo: 'Destaca beneficios claros. Incluye llamada a la acción fuerte.',
};

const plataformaLimites = {
  instagram: 'Máximo 2200 caracteres. Usa emojis estratégicamente.',
  facebook: 'Máximo 500 caracteres para mayor engagement.',
  twitter: 'Máximo 280 caracteres. Directo y conciso.',
  linkedin: 'Máximo 600 caracteres. Tono profesional.',
  google_ads: 'Titular: 30 chars. Descripción: 90 chars. Muy conciso.',
  tiktok: 'Máximo 150 caracteres. Energético y juvenil.',
};

const instruccionTono = tonoInstrucciones[body.tono] || 'Usa un lenguaje claro y efectivo.';
const restriccionPlataforma = plataformaLimites[body.plataforma] || 'Máximo 280 caracteres.';

const prompt = `Eres un experto en marketing digital y copywriting para campañas publicitarias.\n\nCrea un anuncio publicitario con las siguientes especificaciones:\n- Industria: ${body.industria}\n- Plataforma: ${body.plataforma}\n- Tono: ${body.tono}\n- Brief del cliente: ${body.prompt}\n\nInstrucciones de tono: ${instruccionTono}\nRestricciones de plataforma: ${restriccionPlataforma}\n\nDevuelve ÚNICAMENTE el texto del anuncio, sin explicaciones ni formato adicional.\nEl texto debe estar listo para publicarse directamente en ${body.plataforma}.`;

// Pre-build the Gemini request body with proper JSON escaping
const geminiBody = JSON.stringify({
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0.8, topK: 40, topP: 0.95, maxOutputTokens: 1024 }
});

return [{
  json: {
    ...body,
    gemini_prompt: prompt,
    gemini_body: geminiBody
  }
}];

const geminiResponse = $input.first().json;
const promptData = $('Prompt Engineering').first().json;
let generatedText;
try {
  const parts = geminiResponse.candidates[0].content.parts;
  const textPart = parts.find(p => !p.thought && p.text);
  generatedText = textPart ? textPart.text : parts[parts.length-1].text;
} catch(e) {
  generatedText = 'DEBUG_RESPONSE: ' + JSON.stringify(geminiResponse).substring(0, 500);
}
return [{json: {
  ...promptData,
  generated_copy: generatedText
}}];

const body = $input.first().json.body;
const safe = (s) => (s == null ? '' : String(s));
const html = `<!DOCTYPE html><html><body style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:20px;background:#f9fafb"><div style="background:white;border-radius:8px;padding:32px;border:1px solid #e5e7eb"><h1 style="color:#4f46e5;margin:0 0 16px">Hola ${safe(body.cliente_nombre)}</h1><p style="color:#374151;font-size:16px;line-height:1.6">Tu campaña <strong>"${safe(body.campaign_titulo)}"</strong> está lista para tu revisión.</p><div style="background:#f3f4f6;border-left:4px solid #4f46e5;padding:16px;margin:24px 0;border-radius:4px"><p style="color:#6b7280;font-size:12px;text-transform:uppercase;margin:0 0 8px">Vista previa del copy</p><p style="color:#1f2937;font-size:14px;line-height:1.6;margin:0">${safe(body.copy_preview)}</p></div><p style="color:#374151;font-size:14px">Aprueba o rechaza la propuesta desde la app móvil MarketMind IA.</p><hr style="border:none;border-top:1px solid #e5e7eb;margin:32px 0"><p style="color:#9ca3af;font-size:12px;margin:0">Equipo MarketMind IA — ${safe(body.marketero_nombre)}</p></div></body></html>`;
return [{ json: { to_email: body.cliente_email, subject: `Tu campaña "${safe(body.campaign_titulo)}" está lista para aprobación`, html, callback_url: body.callback_url, n8n_callback_token: body.n8n_callback_token, event_type: body.event_type } }];

const body = $input.first().json.body;
const safe = (s) => (s == null ? '' : String(s));
const html = `<!DOCTYPE html><html><body style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:20px;background:#f9fafb"><div style="background:white;border-radius:8px;padding:32px;border:1px solid #e5e7eb;border-top:6px solid #10b981"><h1 style="color:#10b981;margin:0 0 16px">✅ Tu campaña fue aprobada</h1><p style="color:#374151;font-size:16px;line-height:1.6">Hola ${safe(body.marketero_nombre)}, tu campaña <strong>"${safe(body.campaign_titulo)}"</strong> fue aprobada por el cliente.</p><div style="background:#ecfdf5;border-left:4px solid #10b981;padding:16px;margin:24px 0;border-radius:4px"><p style="color:#065f46;font-size:12px;text-transform:uppercase;margin:0 0 8px">Copy aprobado</p><p style="color:#064e3b;font-size:14px;line-height:1.6;margin:0">${safe(body.copy_preview)}</p></div><p style="color:#374151;font-size:14px">Ya puedes proceder a publicarla en la plataforma correspondiente.</p><hr style="border:none;border-top:1px solid #e5e7eb;margin:32px 0"><p style="color:#9ca3af;font-size:12px;margin:0">Equipo MarketMind IA</p></div></body></html>`;
return [{ json: { to_email: body.marketero_email, subject: `✅ Tu campaña "${safe(body.campaign_titulo)}" fue aprobada`, html, callback_url: '', n8n_callback_token: body.n8n_callback_token, event_type: body.event_type } }];

const body = $input.first().json.body;
const safe = (s) => (s == null ? '' : String(s));
const feedback = safe(body.feedback) || 'Sin feedback adicional.';
const html = `<!DOCTYPE html><html><body style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:20px;background:#f9fafb"><div style="background:white;border-radius:8px;padding:32px;border:1px solid #e5e7eb;border-top:6px solid #f97316"><h1 style="color:#f97316;margin:0 0 16px">⚠️ Tu campaña fue rechazada</h1><p style="color:#374151;font-size:16px;line-height:1.6">Hola ${safe(body.marketero_nombre)}, el cliente rechazó la campaña <strong>"${safe(body.campaign_titulo)}"</strong>.</p><div style="background:#fff7ed;border-left:4px solid #f97316;padding:16px;margin:24px 0;border-radius:4px"><p style="color:#9a3412;font-size:12px;text-transform:uppercase;margin:0 0 8px">Feedback del cliente</p><p style="color:#7c2d12;font-size:14px;line-height:1.6;margin:0">${feedback}</p></div><div style="background:#f9fafb;border-left:4px solid #d1d5db;padding:16px;margin:24px 0;border-radius:4px"><p style="color:#6b7280;font-size:12px;text-transform:uppercase;margin:0 0 8px">Copy rechazado</p><p style="color:#1f2937;font-size:14px;line-height:1.6;margin:0">${safe(body.copy_preview)}</p></div><p style="color:#374151;font-size:14px">Puedes regenerar el copy desde el panel admin con los ajustes sugeridos.</p><hr style="border:none;border-top:1px solid #e5e7eb;margin:32px 0"><p style="color:#9ca3af;font-size:12px;margin:0">Equipo MarketMind IA</p></div></body></html>`;
return [{ json: { to_email: body.marketero_email, subject: `⚠️ Tu campaña "${safe(body.campaign_titulo)}" fue rechazada`, html, callback_url: '', n8n_callback_token: body.n8n_callback_token, event_type: body.event_type } }];

const data = $input.first().json;
const imagenPrompt = 'Professional advertising image for a ' + data.industria + ' brand. Campaign concept: ' + data.generated_copy.substring(0, 200) + ' Platform: ' + data.plataforma + '. Style: clean, modern, commercial photography, photorealistic. No text overlay.';
const imagenBody = JSON.stringify({
  instances: [{ prompt: imagenPrompt }],
  parameters: { sampleCount: 1, aspectRatio: "1:1" }
});
return [{ json: { ...data, imagen_prompt: imagenPrompt, imagen_body: imagenBody } }];

const imgResponse = $input.first().json;
const prevData = $('Construir Prompt Imagen').first().json;
let imagen_b64 = null;
try {
  const pred = imgResponse.predictions;
  if (pred && pred[0] && pred[0].bytesBase64Encoded) {
    imagen_b64 = pred[0].bytesBase64Encoded;
  }
} catch (e) {
  // imagen queda null — copy se guarda igual
}
return [{ json: { ...prevData, imagen_b64 } }];
